// Stage 4: one question aimed at the weakest idea in the student's explanation. The question is generated by the
// OS Engine on the server and checked there; the page never sees the answer before the student commits.
import { useEffect, useState } from "react";
import { learnApi } from "../../api.js";
import { Tables } from "../Cards.jsx";
import { PaperQuestion, QuestionPaper } from "../QuestionPaper.jsx";
import Gantt from "../Gantt.jsx";
import Table from "../Table.jsx";
import Thinking from "../Thinking.jsx";

export function Options({ options, value, onChange, disabled, wide = false, correct }) {
  return (
    <div className={`options${wide ? " options--wide" : ""}`} role="radiogroup">
      {options.map((o) => (
        <button key={String(o)} role="radio" aria-checked={value === o} disabled={disabled}
                className={`option${value === o ? " is-picked" : ""}${correct !== undefined && String(correct) === String(o) ? " is-answer" : ""}`}
                onClick={() => onChange(o)}>{String(o)}</button>
      ))}
    </div>
  );
}

function QuestionBody({ q, answer, setAnswer, locked, correct }) {
  if (q.kind === "mcq") {
    return (<><p className="question__prompt">{q.prompt}</p>
      <Options wide options={q.options} value={answer} onChange={setAnswer} disabled={locked} /></>);
  }
  if (q.kind === "decision" || q.kind === "metric") {
    return (
      <>
        <p className="muted small">{q.title}</p>
        <Table {...q.processes} small />
        <Gantt {...q.gantt} span={q.span} title={q.kind === "decision" ? "Chart so far" : "Finished Gantt chart"} />
        {q.ready && <Table {...q.ready} small label="Ready to run" />}
        <p className="question__prompt">{q.prompt}</p>
        {q.kind === "decision"
          ? <Options options={q.options} value={answer} onChange={setAnswer} disabled={locked} correct={correct} />
          : <input className="num-input" type="number" step="1" value={answer ?? ""} disabled={locked} aria-label="Your answer"
                   placeholder="your answer" onChange={(e) => setAnswer(e.target.value === "" ? null : Number(e.target.value))} />}
      </>
    );
  }
  if (q.kind === "semaphore") {
    const [v, o] = answer || [null, null];
    return (
      <>
        <p>Initial value: <b>{q.initial.map(([k, x]) => `${k} = ${x}`).join(", ")}</b></p>
        {q.done.length > 0 && (
          <Table small columns={["#", "Operation", "Value after", "Waiting"]}
                 rows={q.done.map((s, k) => [k + 1, `${s.pid}: ${s.op}(${s.sem})`, s.after, s.queue.join(", ") || "—"])} />
        )}
        <p className="question__prompt">{q.prompt}</p>
        <div className="two-col">
          <div><p className="muted small">New value</p><Options options={q.value_options} value={v} onChange={(x) => setAnswer([x, o])} disabled={locked} /></div>
          <div><p className="muted small">What happens?</p><Options options={q.outcomes} value={o} onChange={(x) => setAnswer([v, x])} disabled={locked} /></div>
        </div>
      </>
    );
  }
  return (
    <>
      <Tables tables={q.tables} />
      <p>Available: <b>{q.available}</b> (resources {q.resources.join(", ")})</p>
      <p className="question__prompt">{q.prompt}</p>
      <Options options={q.options} value={answer} onChange={setAnswer} disabled={locked} correct={correct} />
    </>
  );
}

const ready = (q, a) => (q.kind === "semaphore" ? a && a[0] !== null && a[1] !== null : a !== null && a !== undefined && a !== "");

export default function YourQuestion({ lesson, sid, onExplain }) {
  const [data, setData] = useState(null);
  const [answer, setAnswer] = useState(null);
  const [result, setResult] = useState(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);

  const load = () => {
    setData(null); setAnswer(null); setResult(null); setError(null);
    learnApi.question(sid, lesson.id).then(setData).catch((e) => setError(e.message));
  };
  useEffect(load, [sid, lesson.id]);   // eslint-disable-line react-hooks/exhaustive-deps

  const submit = async () => {
    setBusy(true);
    try { setResult(await learnApi.answer(sid, lesson.id, answer)); } catch (e) { setError(e.message); }
    setBusy(false);
  };

  if (error) return <p className="banner">{error}</p>;
  if (!data) return <Thinking />;
  const why = data.why === "challenge"
    ? "You explained every key idea clearly, so here is a challenge question."
    : !data.explained
      ? <>You skipped explaining, so this checks a key idea. <button className="link-btn" onClick={onExplain}>Explain it first</button> for a question picked from what you say.</>
      : `This checks an idea that was ${data.rating === "partial" ? "unclear" : "missing"} in your explanation.`;
  // on the question paper: an MCQ is ticked like the quiz; the other kinds keep their tables and charts on the sheet
  const q = data.question;
  const mcq = q.kind === "mcq";
  const verdict = result && (
    <div aria-live="polite">
      <p><b>{result.ok ? "Correct!" : `Not quite. The answer is ${result.correct}.`}</b> {result.explanation}</p>
      <p className="qq__idea">The idea behind it: {result.idea}</p>
    </div>
  );
  return (
    <div className="question">
      <QuestionPaper title={`Your question · ${lesson.title}`} meta={[`Question ${data.number}`, "1 mark"]} rules={why}
                     grade={result ? [result.ok ? 1 : 0, 1] : null} foot={result ? "Marked" : "Answer, then submit"}>
        <PaperQuestion n={data.number} text={mcq ? q.prompt : null} marked={!!result} ok={result ? result.ok : undefined}
                       options={mcq ? q.options : null} picked={mcq && answer !== null ? q.options.indexOf(answer) : null}
                       answer={mcq && result ? q.options.indexOf(result.correct) : null} why={verdict}
                       onPick={(k) => setAnswer(q.options[k])}>
          {!mcq && <QuestionBody q={q} answer={answer} setAnswer={setAnswer} locked={!!result} correct={result?.correct} />}
        </PaperQuestion>
      </QuestionPaper>
      {!result ? (
        <button className="primary" disabled={busy || !ready(q, answer)} onClick={submit}>Submit answer</button>
      ) : (
        result.more && <div className="row-actions"><button className="secondary" onClick={load}>Another question</button></div>
      )}
    </div>
  );
}
